from lib import *
S = SS('h18')
steps = [
    step("服务端前 2 次返回 Unavailable。没有重试配置:服务端只收到 1 次,调用失败 Unavailable。在服务配置里加 retryPolicy(maxAttempts 4,initialBackoff 50 ms,backoffMultiplier 2,retryableStatusCodes 为 UNAVAILABLE):服务端收到 3 次,调用成功,总耗时 171.8 ms,两次重试前的等待是 57 ms、112 ms;线上三个请求的 grpc-previous-rpc-attempts 头分别是 无、1、2(客户端告诉服务端这是第几次重试)。重复 8 次,第一次重试前的等待在 45~58 ms 之间,第二次在 87~121 ms 之间,符合源码里“退避 = initialBackoff × multiplier^n,再乘以 0.8~1.2 的随机数”。", t=tl(S(1)), done=lidx(S(1), '再重复 8 次'), mark=lidx(S(1), '有配置:'), b=bars([['没有配置:服务端收到', 1, '1'], ['有 retryPolicy:服务端收到', 3, '3'], ['有 retryPolicy:总耗时 ms', 171.8, '171.8']], 180, mark=[0], done=[1, 2]), kv=KV([['没有配置', '1 次,失败'], ['有 retryPolicy', '3 次,第 3 次成功'], ['重试前的等待', '约 50 ms、约 100 ms(±20%)']], ['有 retryPolicy'])),
    step("哪些情况重试、最多几次:服务端返回 Internal,而 retryableStatusCodes 里只有 UNAVAILABLE:服务端收到 1 次,不重试。一直返回 Unavailable:配置 maxAttempts = 4,服务端收到 4 次,最终错误 message 以“max retries exhausted: failed after 4 attempts”开头;配置 maxAttempts = 10,服务端只收到 5 次——客户端把服务端配置的 maxAttempts 限制到最大 5(读源码 dialoptions.go:defaultMaxCallAttempts = 5,可以用 WithMaxCallAttempts 调整,注释说这是为了防止 DNS 带来的服务配置过度放大重试)。", t=tl(S(2)), done=lidx(S(2), '配置 maxAttempts = 10'), mark=lidx(S(2), '服务端返回 Internal'), b=bars([['Internal(不在重试码里):服务端收到', 1, '1'], ['maxAttempts = 4:服务端收到', 4, '4'], ['maxAttempts = 10:服务端收到', 5, '5']], 6, mark=[0], done=[1, 2]), kv=KV([['不在 retryableStatusCodes', '不重试'], ['maxAttempts = 4', '4 次'], ['maxAttempts = 10', '被限制为 5 次']], ['maxAttempts = 10'])),
    step("响应头已经发出就不再重试。服务端前 2 次都返回 Unavailable:handler 里没有设置头时,服务端收到 3 次、调用成功;但 handler 里先 grpc.SetHeader(x-h) 再返回 Unavailable,服务端只收到 1 次,调用失败。读源码 stream.go 的 shouldRetry:只有“Trailers-Only”的响应(没有先发过响应头)才会重试。所以服务端拦截器、中间件在失败的响应上先写了响应头(比如上一篇里的 x-served-by),重试就不会发生。", t=tl(S(3)), done=lidx(S(3), 'SetHeader=true'), mark=lidx(S(3), 'SetHeader=false'), b=bars([['没有 SetHeader:服务端收到', 3, '3'], ['先 SetHeader:服务端收到', 1, '1']], 4, mark=[1], done=[0]), kv=KV([['没有设置头', '重试,第 3 次成功'], ['先 SetHeader 再失败', '不重试,1 次'], ['原因', '响应不再是 Trailers-Only']], ['原因'])),
    step("retry 和 deadline:initialBackoff 100 ms、multiplier 2,调用的 deadline 250 ms,服务端一直返回 Unavailable。服务端收到 2 次(间隔 105 ms),调用在 252.2 ms 后返回 DeadlineExceeded——第二次失败之后的退避按公式是第一次的 2 倍(推算,没有单独测),落在 deadline 之外,于是在退避等待中因为 deadline 到期而结束,没有第三次尝试。重试的总时间被调用的 deadline 约束;不要把重试的总时间设得比 deadline 还长(第 33 篇讲超时叠加)。", t=tl(S(4)), done=lidx(S(4), '服务端收到 2 次'), mark=lidx(S(4), '服务端收到 2 次'), b=bars([['服务端收到的次数', 2, '2'], ['调用返回的时刻 ms(deadline 250)', 252.2, '252.2']], 260, done=[0, 1]), kv=KV([['第 1、2 次到达间隔', '105 ms'], ['下一次退避', '公式给出第一次的 2 倍,超过 deadline(推算)'], ['最终', 'DeadlineExceeded,没有第 3 次']], ['最终'])),
    step("服务端可以用 trailer grpc-retry-pushback-ms 告诉客户端等多久:设成 300,客户端按 300 ms 等(两次到达间隔 303 ms,总耗时 305.5 ms,忽略了本地配置的 50 ms 退避),重试成功;设成 -1,客户端不再重试(服务端只收到 1 次,总耗时 1.3 ms,调用失败)。pushback 让服务端在过载时能控制客户端的重试节奏,或者明确说“别再试了”。", t=tl(S(5)), done=lidx(S(5), 'pushback = -1'), mark=lidx(S(5), 'pushback = 300'), b=bars([['pushback = 300:两次到达间隔 ms', 303, '303'], ['pushback = -1:服务端收到', 1, '1']], 320, mark=[0], done=[1]), kv=KV([['pushback = 300', '等 300 ms 再重试(本地退避被忽略)'], ['pushback = -1', '不重试'], ['谁来写', '服务端的 trailer']], ['pushback = 300'])),
    step("重试需要把请求缓存下来以便重发。默认缓冲 256 KiB(读源码 rpc_util.go)。请求 100 KiB 的 Unary:服务端收到 3 次,重试成功;请求 300 KiB:服务端只收到 1 次,调用失败——请求超过缓冲就不能重试了。大请求的调用如果想重试,可以用 WithMaxRetryRPCBufferSize 加大缓冲(本篇没有测加大之后的行为)。", t=tl(S(6)), done=lidx(S(6), '请求 300 KiB'), mark=lidx(S(6), '请求 100 KiB'), b=bars([['请求 100 KiB:服务端收到', 3, '3'], ['请求 300 KiB:服务端收到', 1, '1']], 4, mark=[1], done=[0]), kv=KV([['缓冲上限', '256 KiB(默认)'], ['100 KiB', '可重试,3 次'], ['300 KiB', '不能重试,1 次']], ['缓冲上限'])),
    step("hedging(对冲:不等第一次的结果,隔一段时间同时发第二次)。服务端第一次请求要 600 ms,之后的很快;服务配置里只写 hedgingPolicy(maxAttempts 3,hedgingDelay 100 ms):服务端只收到 1 次,总耗时 605.1 ms,成功——hedging 没有生效。读源码:stream.go 里只有一句“TODO(hedging): hedging will have multiple attempts simultaneously”,整个 grpc-go v1.84.0 没有实现 hedging(配置写了也被忽略,不报错)。要对冲得自己在应用层并发发请求。", t=tl(S(7)), done=lidx(S(7), 'hedgingPolicy:'), mark=lidx(S(7), 'hedgingPolicy:'), b=bars([['服务端收到的次数', 1, '1'], ['总耗时 ms(第一次要 600 ms)', 605.1, '605.1']], 650, done=[0, 1]), kv=KV([['hedgingPolicy', '被忽略,只发 1 次'], ['耗时', '605.1 ms,等满第一次'], ['源码', 'TODO(hedging)']], ['hedgingPolicy'])),
]
A = mkarth('h18', 18, 'gRPC,重试,retryPolicy,service config,退避,pushback,hedging,Go,真实验证,动画演示',
    '实测 gRPC 服务配置里的重试策略:重试几次、等多久(退避带 ±20% 随机)、哪些错误码、最多 5 次的客户端上限、响应头发出后不重试、请求超过 256 KiB 不重试、服务端 pushback,以及 grpc-go 没有实现 hedging。',
    'gRPC 的重试是怎么工作的?配置里写 maxAttempts 就一定会试那么多次吗?什么情况下不会重试?hedging 呢?这篇用一个会按次数失败的服务端逐项验证。',
    [('3 次 / 171.8 ms', '前 2 次 Unavailable、配置 retryPolicy 后:服务端收到的次数与总耗时'), ('10 → 5', '服务配置里 maxAttempts = 10 时,客户端实际只尝试 5 次'), ('1 次', '失败的响应带了响应头、或请求超过 256 KiB、或 hedging 配置下:服务端收到的次数')],
    [('retryPolicy', '<p>写在服务配置的 methodConfig 里:maxAttempts、initialBackoff、maxBackoff、backoffMultiplier、retryableStatusCodes。每次重试前等待 initialBackoff × multiplier^n,再乘以 0.8~1.2 的随机数。重试的请求会带 grpc-previous-rpc-attempts 头。</p>'),
     ('限制', '<p>错误码必须在 retryableStatusCodes 里;客户端把 maxAttempts 限制到 5(WithMaxCallAttempts 可调)。</p>'),
     ('什么时候不重试', '<p>响应头已经发出(不是 Trailers-Only)就不重试;请求已经超过重试缓冲(默认 256 KiB)也不重试。所以失败的响应上不要先写响应头。</p>'),
     ('和 deadline 的关系', '<p>重试的总时间受调用的 deadline 约束,退避等待期间 deadline 到期就直接以 DeadlineExceeded 结束。</p>'),
     ('服务端 pushback', '<p>trailer grpc-retry-pushback-ms 为非负数时,客户端按它等待;为负数时不再重试。</p>'),
     ('请求缓冲', '<p>重试要重发请求,所以客户端要把请求缓存起来;缓冲有上限。</p>'),
     ('hedging', '<p>grpc-go 当前没有实现 hedging(源码里只有 TODO),配置里写了会被忽略。</p>')],
    steps,
    [ENV_H + '。服务端按“前 N 次失败”的方式记录每次到达的时刻;grpc-previous-rpc-attempts 来自抓包代理;“最多 5 次”“Trailers-Only 才重试”“pushback”“256 KiB 缓冲”“hedging 没有实现”读自 grpc-go 源码(service_config.go、stream.go、dialoptions.go、rpc_util.go)并用实验核对',
     '没有验证:重试节流(retryThrottling,第 19 篇);流式 RPC 的重试(只测了 Unary);连接层面的透明重试(transparent retry,代码里有但本篇没有构造场景);WithMaxRetryRPCBufferSize 加大缓冲之后的行为;其它语言的重试实现;hedging 在其它实现(如 Java、C++)里的行为'],
    '重试')
